export interface ControllableClock extends Clock {
  set(time: string | DateTime): void;
  reset(): void;
  getIso(): string;
}

export class DatabaseControllableClock implements ControllableClock {
  constructor(private db: Database.Database) {}

  now(): DateTime {
    return DateTime.fromISO(this.getIso(), { setZone: true });
  }

  getIso(): string {
    const row = this.db.prepare('SELECT agora FROM relogio_estado WHERE id = 1').get() as { agora: string };
    console.log('DatabaseControllableClock.getIso returning:', row ? row.agora : 'default');
    return row ? row.agora : '2026-10-13T09:00:00-03:00';
  }

  set(time: string | DateTime): void {
    const iso = typeof time === 'string' ? time : time.toISO();
    if (!iso) throw new Error('Data inválida');
    console.log('DatabaseControllableClock.set updating DB with:', iso);
    const res = this.db.prepare('UPDATE relogio_estado SET agora = ? WHERE id = 1').run(iso);
    console.log('UPDATE result changes:', res.changes);
  }

  reset(): void {
    console.log('DatabaseControllableClock.reset');
    this.db.prepare('UPDATE relogio_estado SET agora = ? WHERE id = 1').run('2026-10-13T09:00:00-03:00');
  }
}

import { DateTime } from 'luxon';
import Database from 'better-sqlite3';
import { Clock } from './clock.js';

export interface ControllableClock extends Clock {
  set(time: string | DateTime): void;
  reset(): void;
  getIso(): string;
}

export class DatabaseControllableClock implements ControllableClock {
  constructor(private db: Database.Database) {}

  now(): DateTime {
    return DateTime.fromISO(this.getIso(), { setZone: true });
  }

  getIso(): string {
    const row = this.db.prepare('SELECT agora FROM relogio_estado WHERE id = 1').get() as { agora: string };
    return row ? row.agora : '2026-10-13T09:00:00-03:00';
  }

  set(time: string | DateTime): void {
    const iso = typeof time === 'string' ? time : time.toISO();
    if (!iso) throw new Error('Data inválida');
    this.db.prepare('INSERT OR REPLACE INTO relogio_estado (id, agora) VALUES (1, ?)').run(iso);
  }

  reset(): void {
    this.db.prepare('INSERT OR REPLACE INTO relogio_estado (id, agora) VALUES (1, ?)').run('2026-10-13T09:00:00-03:00');
  }
}

import Database from 'better-sqlite3';
import { Clock } from '../clock/clock.js';
import { DatabaseControllableClock } from '../clock/controllable-clock.js';

export function runSeed(db: Database.Database, clock?: Clock): void {
  runReset(db, clock);
}

export function runReset(db: Database.Database, clock?: Clock): void {
  const insertUsuario = db.prepare('INSERT OR REPLACE INTO usuarios (id, nome, papel) VALUES (?, ?, ?)');
  const usuarios = [
    ['org-ana', 'Ana Beatriz Lima', 'organizacao'],
    ['org-bruno', 'Bruno Tavares', 'organizacao'],
    ['p-carla', 'Carla Mendes Souza', 'participante'],
    ['p-diego', 'Diego Alves', 'participante'],
    ['p-elisa', 'Elisa Fernandes da Rocha', 'participante'],
    ['p-fabio', 'Fábio Nogueira', 'participante'],
    ['p-gabriela', 'Gabriela Moura Castro', 'participante'],
    ['p-heitor', 'Heitor Campos', 'participante'],
    ['p-isadora', 'Isadora Ribeiro dos Santos', 'participante'],
    ['p-joao', 'João Pedro Martins', 'participante']
  ];

  const insertSala = db.prepare('INSERT OR REPLACE INTO salas (id, nome, capacidade) VALUES (?, ?, ?)');
  const salas = [
    ['auditorio', 'Auditório Central', 200],
    ['sala-101', 'Sala 101', 40],
    ['sala-102', 'Sala 102', 40],
    ['lab-3', 'Laboratório 3', 20]
  ];

  const insertRelogio = db.prepare('INSERT OR REPLACE INTO relogio_estado (id, agora) VALUES (1, ?)');

  db.transaction(() => {
    db.prepare('DELETE FROM encontros').run();
    db.prepare('DELETE FROM atividades').run();

    for (const u of usuarios) {
      insertUsuario.run(u[0], u[1], u[2]);
    }
    for (const s of salas) {
      insertSala.run(s[0], s[1], s[2]);
    }

    if (clock && clock instanceof DatabaseControllableClock) {
      clock.reset();
    } else {
      insertRelogio.run('2026-10-13T09:00:00-03:00');
    }
  })();
}

import express, { Request, Response, NextFunction } from 'express';
import cors from 'cors';
import { z } from 'zod';
import { createDatabase } from './db/connection.js';
import { runMigrations } from './db/migrate.js';
import { runSeed, runReset } from './db/seed.js';
import { Clock, RealClock } from './clock/clock.js';
import { DatabaseControllableClock, ControllableClock } from './clock/controllable-clock.js';
import { NeutralM2Adapter } from './integrations/m2-port.js';

export interface AppOptions {
  dbPath?: string;
  clock?: Clock;
  modoTeste?: boolean;
}

export function createApp(options?: AppOptions | string) {
  const opts: AppOptions = typeof options === 'string' ? { dbPath: options } : (options || {});
  const dbPath = opts.dbPath;
  const modoTeste = opts.modoTeste !== undefined ? opts.modoTeste : (process.env.MODO_TESTE === '1');

  const app = express();

  app.use(cors({
    origin: '*',
    allowedHeaders: ['Content-Type', 'X-Usuario']
  }));
  app.use(express.json());

  const db = createDatabase(dbPath);
  runMigrations(db);

  const clock = opts.clock || (modoTeste ? new DatabaseControllableClock(db) : new RealClock());

  if (modoTeste && !opts.clock && clock instanceof DatabaseControllableClock) {
    runSeed(db, clock);
  } else {
    runSeed(db);
  }

  const m2Port = new NeutralM2Adapter();

  // Modo de teste routes (when MODO_TESTE=1)
  if (modoTeste) {
    app.post('/_teste/reset', (_req: Request, res: Response) => {
      runReset(db, clock instanceof DatabaseControllableClock ? clock : undefined);
      res.status(204).send();
    });

    app.get('/_teste/relogio', (_req: Request, res: Response) => {
      const agoraStr = 'getIso' in clock ? (clock as ControllableClock).getIso() : clock.now().toISO() || '2026-10-13T09:00:00-03:00';
      res.json({ agora: agoraStr });
    });

    const isoSchema = z.string().datetime({ offset: true });

    app.put('/_teste/relogio', (req: Request, res: Response) => {
      const { agora } = req.body || {};
      const result = isoSchema.safeParse(agora);
      if (!result.success) {
        res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: 'Formato de data inválido. Deve ser ISO 8601 com fuso.' });
        return;
      }
      if ('set' in clock && typeof (clock as ControllableClock).set === 'function') {
        (clock as ControllableClock).set(result.data);
      }
      const agoraStr = 'getIso' in clock ? (clock as ControllableClock).getIso() : clock.now().toISO() || result.data;
      res.json({ agora: agoraStr });
    });
  } else {
    app.all('/_teste/*', (_req: Request, res: Response) => {
      res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Modo de teste desativado' });
    });
  }

  const requireUser = (req: Request, res: Response, next: NextFunction) => {
    const usuarioId = req.headers['x-usuario'] as string;
    if (!usuarioId) {
      res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Cabeçalho X-Usuario ausente' });
      return;
    }
    const user = db.prepare('SELECT id, nome, papel FROM usuarios WHERE id = ?').get(usuarioId);
    if (!user) {
      res.status(401).json({ erro: 'USUARIO_DESCONHECIDO', mensagem: 'Usuário desconhecido' });
      return;
    }
    (req as any).user = user;
    next();
  };

  app.get('/salas', requireUser, (_req: Request, res: Response) => {
    const salas = db.prepare('SELECT id, nome, capacidade FROM salas').all();
    res.json(salas);
  });

  app.get('/atividades', requireUser, (_req: Request, res: Response) => {
    const atividades = db.prepare('SELECT id, titulo, tipo, sala_id as salaId, vagas, carga_horaria_minutos as cargaHorariaMinutos, cancelada FROM atividades').all();
    const result = atividades.map((atv: any) => ({
      id: atv.id,
      titulo: atv.titulo,
      tipo: atv.tipo,
      salaId: atv.salaId,
      vagas: atv.vagas,
      cargaHorariaMinutos: atv.cargaHorariaMinutos,
      situacao: atv.cancelada ? 'cancelada' : 'prevista',
      ocupadas: m2Port.getOcupadas(atv.id),
      vagasRestantes: atv.vagas - m2Port.getOcupadas(atv.id),
      emEspera: m2Port.getEmEspera(atv.id),
      encontros: db.prepare('SELECT id, inicio, fim FROM encontros WHERE atividade_id = ?').all(atv.id)
    }));
    res.json(result);
  });

  app.use((_req: Request, res: Response) => {
    res.status(404).json({ erro: 'NAO_ENCONTRADO', mensagem: 'Recurso não encontrado' });
  });

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    res.status(422).json({ erro: 'DADOS_INVALIDOS', mensagem: err.message || 'Erro de validação' });
  });

  return app;
}

